from pathlib import Path
from PIL import Image
import json,base64,hashlib,io
R=Path(__file__).resolve().parents[1];M=json.loads((R/'kit.json').read_text());assets={};ids={};night_sources={}
def embed(p):
 raw=p.read_bytes();im=Image.open(p).convert('RGBA');b=io.BytesIO();im.save(b,format='WEBP',lossless=True,exact=True,method=4)
 mime='image/png'
 if len(b.getvalue())<len(raw):raw=b.getvalue();mime='image/webp'
 h=hashlib.sha256(raw).hexdigest()
 if h not in ids:
  key='i'+str(len(ids));ids[h]=key;assets[key]='data:'+mime+';base64,'+base64.b64encode(raw).decode()
 return ids[h]
rooms=[]
for r in M['salles']:
 q=dict(r);q['layers']={};q['views']={};q['empty']={}
 for mode in ['jour','nuit']:
  q['layers'][mode]=[];q['empty'][mode]=[]
  for index,l in enumerate(M['calques']):
   p=R/'calques'/r['dossier']/mode/(l['id']+'.png');empty=Image.open(p).getbbox() is None;q['empty'][mode].append(empty)
   if empty:q['layers'][mode].append(None)
   elif mode=='jour':q['layers'][mode].append(embed(p))
   elif index in [0,8]:q['layers'][mode].append(q['layers']['jour'][index])
   else:
    original=q['layers']['jour'][index];derived='night_'+original;night_sources[derived]=original;q['layers'][mode].append(derived)
 for mode in M['ambiances']:q['views'][mode]=embed(R/'fenetres_exterieur'/r['id']/(mode+'.png'))
 im=Image.open(R/r['fichiers']['jour']['png']).convert('RGBA');im.thumbnail((250,170),Image.Resampling.NEAREST);b=io.BytesIO();im.save(b,format='PNG',optimize=True)
 q['thumb']='data:image/png;base64,'+base64.b64encode(b.getvalue()).decode();rooms.append(q)
landscapes={m:embed(R/'exterieur'/(m+'.png')) for m in M['ambiances']}
DATA={'rooms':rooms,'layers':M['calques'],'ambiences':M['ambiances'],'landscapes':landscapes,'assets':assets,'night_sources':night_sources}
html='''<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Guilde Treehouse — passages ouverts PMD</title><style>
:root{color-scheme:dark;--bg:#171b18;--panel:#242a21;--border:#3e4735;--ink:#f2ecda;--muted:#a7b19a;--gold:#e7c37a}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:14px/1.45 system-ui,-apple-system,"Segoe UI",sans-serif}main{max-width:1370px;margin:auto;padding:24px 22px 32px}header{display:flex;gap:20px;align-items:center;margin-bottom:20px}h1{font-size:28px;line-height:1.2;margin:5px 0 9px;letter-spacing:-.5px}.eyebrow{color:var(--gold);font-weight:700;font-size:10px;letter-spacing:2px}.sub{font-size:13px;color:var(--muted)}.badge{margin-left:auto;padding:6px 11px;border:1px solid #70814e;border-radius:20px;color:#d6e7b3;font-size:11px;white-space:nowrap}button,select,input{font:inherit}button,select{border:1px solid var(--border);border-radius:7px;background:#2a3126;color:var(--ink);padding:8px 11px;cursor:pointer}button.on{background:var(--gold);border-color:var(--gold);color:#2b2314;font-weight:650}button:hover,select:hover{border-color:#8d986e}button:focus-visible,select:focus-visible,input:focus-visible{outline:2px solid var(--gold);outline-offset:2px}.bar{display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin-bottom:12px}.group{display:flex;gap:5px}.push{margin-left:auto}.bar label{font-size:11px;color:var(--muted)}#weather{font-size:12px;min-width:132px}#room{max-width:300px}.work{display:grid;grid-template-columns:minmax(0,1fr) 260px;gap:13px}.scene,.layers{border:1px solid var(--border);border-radius:10px;overflow:hidden;background:var(--panel)}.head{padding:11px 14px;border-bottom:1px solid var(--border);display:flex;align-items:center;gap:12px}.head strong{font-size:13px}.dimensions{font:10px ui-monospace,Consolas,monospace;margin-left:auto;color:var(--muted)}.stage{min-height:400px;background:#12142f;display:flex;align-items:center;justify-content:flex-start;overflow:auto;padding:12px}.stage.magenta{background:#f0f}canvas{display:block;image-rendering:pixelated;image-rendering:crisp-edges;flex-shrink:0;margin:auto}.foot{border-top:1px solid var(--border);padding:10px 13px;display:flex;align-items:center;gap:11px;flex-wrap:wrap;font-size:11px;color:var(--muted)}.foot select{font-size:10px;padding:4px 7px}.foot label{cursor:pointer;display:flex;gap:5px;align-items:center}input{accent-color:var(--gold)}.foot .group button{font-size:10px;padding:5px 8px}.layers{padding:14px}.layers h2{font-size:14px;margin:0 0 5px}.layers p{font-size:10px;color:var(--muted);margin:0 0 8px}.layer{display:flex;gap:7px;align-items:center;font-size:11px;border-bottom:1px solid #384031;padding:9px 0;cursor:pointer}.layer small{margin-left:auto;color:#88957b;font-size:9px;white-space:nowrap}.layer.empty{color:#7f8e78;cursor:default}.layer input{margin:0;flex-shrink:0}.reset{width:100%;font-size:11px;margin-top:12px}.note{margin:12px 0 22px;padding:11px 14px;background:#272e23;border-left:3px solid var(--gold);font-size:12px;color:#d6d8c3}.section-head{display:flex;align-items:baseline;justify-content:space-between;margin:20px 0 10px}.section-head h2{font-size:15px;margin:0}.section-head small{font-size:10px;color:var(--muted)}.thumbs{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:8px}.thumb{padding:0;overflow:hidden;text-align:left}.thumb img{display:block;width:100%;height:110px;object-fit:contain;background:#12142f;image-rendering:pixelated;padding:4px}.thumb span{display:block;padding:7px 8px;font-size:10px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.thumb.on{background:#3b3827;color:var(--ink)}.thumb b{color:var(--gold);margin-right:5px}.landscapes{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}.landscapes button{padding:0;overflow:hidden;text-align:left}.landscapes img{display:block;width:100%;height:auto;image-rendering:pixelated}.landscapes span{display:block;padding:8px 11px;font-size:11px}.hidden{display:none!important}footer{margin-top:23px;border-top:1px solid var(--border);padding-top:13px;font-size:11px;color:var(--muted);display:flex;gap:20px;justify-content:space-between}.error{color:#ffbfa9}
@media(max-width:950px){main{padding:20px 15px}.work{grid-template-columns:minmax(0,1fr) 225px}.thumbs{grid-template-columns:repeat(4,minmax(0,1fr))}.stage{min-height:330px}.dimensions{font-size:9px}}
@media(max-width:680px){main{padding:15px 10px 25px}h1{font-size:22px}.badge{display:none}.sub{font-size:11px}.bar{gap:7px}.bar button,.bar select{font-size:11px;padding:7px 9px}#room{width:100%;max-width:none;order:3}.work{grid-template-columns:minmax(0,1fr)}.stage{min-height:240px;padding:8px}.head{flex-wrap:wrap;padding:10px}.head strong{font-size:12px}.layers{padding:12px}.layer-list{display:grid;grid-template-columns:1fr 1fr;column-gap:16px}.layer{font-size:10px}.note{font-size:11px}.thumbs{grid-template-columns:repeat(3,minmax(0,1fr))}.thumb img{height:88px}.thumb span{font-size:9px;padding:7px 5px}.landscapes{grid-template-columns:repeat(2,minmax(0,1fr))}.foot{font-size:10px}.section-head small{font-size:9px}footer{flex-direction:column;gap:8px;font-size:10px}}
</style></head><body><main><header><div><div class="eyebrow">GUILDE TREEHOUSE · CORRECTION PMD</div><h1>Des passages, pas des portes partout</h1><div class="sub">Contour interrompu, plancher continu · fenêtres évidées · paysage séparé · salle vide</div></div><div class="badge">Fixe · grille 8 px</div></header>
<div class="bar"><div class="group"><button class="on" id="tabrooms">Les 12 salles</button><button id="tabland">Les 6 paysages</button></div><select id="room" aria-label="Salle"></select><div class="group push"><button data-mode="jour" class="on">Intérieur jour</button><button data-mode="nuit">Intérieur nuit</button></div><label for="weather">Extérieur</label><select id="weather" aria-label="Ambiance du paysage"></select></div>
<div id="roomview"><div class="work"><section class="scene"><div class="head"><strong id="title"></strong><span class="dimensions" id="dimensions"></span></div><div class="stage" id="stage"><canvas id="map" width="1280" height="544" role="img" aria-label="Guilde à calques indépendants"></canvas></div><div class="foot"><div class="group"><button class="on" id="composite">Vue composée</button><button id="base">Base seule — magenta</button></div><label><input id="grid" type="checkbox">Grille 8 × 8</label><select id="zoom" aria-label="Zoom"><option value="fit">Ajuster</option><option value="1">1× natif</option><option value="2">2× pixels</option></select><span id="cells" class="push"></span></div></section><aside class="layers"><h2>Calques indépendants</h2><p>La vue extérieure se place derrière les cadres, jamais dans le fond de la pièce.</p><div class="layer-list" id="layers"></div><button class="reset" id="reset">Rétablir les calques</button></aside></div><div class="note" id="note"></div><div class="section-head"><h2>Les 12 pièces corrigées</h2><small>Une seule porte visible : au nord du hall, vers le bureau</small></div><div id="thumbs" class="thumbs"></div></div>
<div id="landview" class="hidden"><div class="section-head"><h2>Un même paysage, six ambiances</h2><small>Même géographie, vues interchangeables et fixes</small></div><div id="lands" class="landscapes"></div></div>
<footer><div>Les côtés et le sud sont des continuités de sol, sans battant ni portique ajouté.<br>Dans le hall, le tronc et l’échelle continuent hors du bord supérieur.</div><div>PNG transparents + variantes magenta · Aseprite · Tiled<br>Décorations et objets restent sur leur banque séparée.</div></footer></main><script>
const DATA=__DATA__;const $=s=>document.querySelector(s);const C=$('#map'),ctx=C.getContext('2d');let id='02',mode='jour',weather='jour',ready=false,magenta=false,showLand=false;const imgs={},vis=DATA.layers.map((_,i)=>![6,7,9].includes(i));const names={jour:'Jour',nuit:'Nuit',crepuscule:'Crépuscule',aube:'Aube',soir:'Soir',orageux:'Orageux'};
function room(){return DATA.rooms.find(r=>r.id===id)}
function fit(){if(!ready||showLand)return;const r=room(),z=$('#zoom').value;let s=z==='fit'?Math.min(($('#stage').clientWidth-22)/r.dimensions[0],(innerWidth<680?390:530)/r.dimensions[1],1.6):+z;s=Math.max(.15,s);C.style.width=(r.dimensions[0]*s)+'px';C.style.height=(r.dimensions[1]*s)+'px'}
function draw(){if(!ready)return;const r=room();ctx.imageSmoothingEnabled=false;ctx.clearRect(0,0,C.width,C.height);if(vis[0]&&!magenta)ctx.drawImage(imgs[r.views[weather]],0,0);r.layers[mode].forEach((key,i)=>{if(i>0&&key&&vis[i])ctx.drawImage(imgs[key],0,0)});if($('#grid').checked){ctx.save();ctx.lineWidth=1;for(let x=0;x<C.width;x+=8){ctx.strokeStyle=x%64?'rgba(248,225,161,.12)':'rgba(248,225,161,.31)';ctx.beginPath();ctx.moveTo(x+.5,0);ctx.lineTo(x+.5,C.height);ctx.stroke()}for(let y=0;y<C.height;y+=8){ctx.strokeStyle=y%64?'rgba(248,225,161,.12)':'rgba(248,225,161,.31)';ctx.beginPath();ctx.moveTo(0,y+.5);ctx.lineTo(C.width,y+.5);ctx.stroke()}ctx.restore()}}
function update(){if(!ready)return;const r=room();C.width=r.dimensions[0];C.height=r.dimensions[1];$('#title').textContent=id+' · '+r.nom;$('#dimensions').textContent=r.dimensions.join(' × ')+' px';$('#cells').textContent=r.cellules.join(' × ')+' cellules';$('#room').value=id;$('#weather').value=weather;$('#stage').classList.toggle('magenta',magenta);$('#composite').classList.toggle('on',!magenta);$('#base').classList.toggle('on',magenta);$('#note').textContent=id==='02'?'Hall : passage ouvert à l’ouest et au sud, tronc/échelle hors champ en haut. La seule porte fermée est au nord, vers le bureau du maître.':('Accès : '+r.acces.join(' · ')+'. Le sol traverse directement la rupture du contour ; aucun battant ni portique ne ferme ces passages.'+(r.trous_fenetres?' Les fenêtres ne contiennent pas de paysage dans la base.':' Cette salle ne possède pas de fenêtre vitrée.'));$('#layers').innerHTML='';DATA.layers.forEach((l,i)=>{let empty=i===0?!r.trous_fenetres:r.empty[mode][i];const label=document.createElement('label');label.className='layer'+(empty?' empty':'');const cb=document.createElement('input');cb.type='checkbox';cb.dataset.layer=i;cb.disabled=empty;cb.checked=!empty&&vis[i]&&!(i===0&&magenta);cb.setAttribute('aria-label',l.nom);cb.onchange=()=>{vis[i]=cb.checked;if(i===0&&cb.checked)magenta=false;$('#stage').classList.toggle('magenta',magenta);draw()};const text=document.createElement('span');text.textContent=l.nom.replace(' — vide','');label.append(cb,text);if(empty){const tag=document.createElement('small');tag.textContent='vide';label.append(tag)}$('#layers').append(label)});document.querySelectorAll('[data-mode]').forEach(b=>b.classList.toggle('on',b.dataset.mode===mode));document.querySelectorAll('.thumb').forEach(b=>b.classList.toggle('on',b.dataset.id===id));document.querySelectorAll('.land').forEach(b=>b.classList.toggle('on',b.dataset.weather===weather));fit();draw()}
function tabs(land){showLand=land;$('#roomview').classList.toggle('hidden',land);$('#landview').classList.toggle('hidden',!land);$('#tabrooms').classList.toggle('on',!land);$('#tabland').classList.toggle('on',land);$('#room').classList.toggle('hidden',land);if(!land)fit()}
DATA.rooms.forEach(r=>{const o=document.createElement('option');o.value=r.id;o.textContent=r.id+' — '+r.nom;$('#room').append(o);const b=document.createElement('button');b.className='thumb';b.dataset.id=r.id;const im=document.createElement('img');im.src=r.thumb;im.alt=r.nom;const t=document.createElement('span'),n=document.createElement('b');n.textContent=r.id;t.append(n,document.createTextNode(r.nom));b.append(im,t);b.onclick=()=>{id=r.id;update()};$('#thumbs').append(b)});DATA.ambiences.forEach(w=>{const o=document.createElement('option');o.value=w;o.textContent=names[w];$('#weather').append(o);const b=document.createElement('button');b.className='land';b.dataset.weather=w;const im=document.createElement('img');im.src=DATA.assets[DATA.landscapes[w]];im.alt='Paysage '+names[w];const t=document.createElement('span');t.textContent=names[w];b.append(im,t);b.onclick=()=>{weather=w;update()};$('#lands').append(b)});
$('#room').onchange=e=>{id=e.target.value;update()};$('#weather').onchange=e=>{weather=e.target.value;update()};document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;update()});$('#base').onclick=()=>{magenta=true;update()};$('#composite').onclick=()=>{magenta=false;vis[0]=true;update()};$('#reset').onclick=()=>{DATA.layers.forEach((_,i)=>vis[i]=![6,7,9].includes(i));magenta=false;update()};$('#grid').onchange=draw;$('#zoom').onchange=fit;$('#tabland').onclick=()=>tabs(true);$('#tabrooms').onclick=()=>tabs(false);window.addEventListener('resize',fit);
Promise.all(Object.entries(DATA.assets).map(([k,url])=>new Promise((resolve,reject)=>{const im=new Image();im.onload=()=>{imgs[k]=im;resolve()};im.onerror=()=>reject(new Error(k));im.src=url}))).then(()=>{const even=v=>{const n=Math.floor(v),f=v-n;return Math.abs(f-.5)<1e-9?n+(n%2):Math.round(v)};Object.entries(DATA.night_sources).forEach(([key,source])=>{const im=imgs[source],c=document.createElement('canvas');c.width=im.naturalWidth||im.width;c.height=im.naturalHeight||im.height;const t=c.getContext('2d');t.drawImage(im,0,0);const data=t.getImageData(0,0,c.width,c.height),p=data.data;for(let i=0;i<p.length;i+=4){if(p[i+3]){p[i]=even(p[i]*.36+9);p[i+1]=even(p[i+1]*.34+10);p[i+2]=even(p[i+2]*.43+19)}else p[i]=p[i+1]=p[i+2]=0}t.putImageData(data,0,0);imgs[key]=c});ready=true;update();document.body.dataset.ready='true'}).catch(e=>{$('#title').textContent='Erreur de chargement : '+e.message});
</script></body></html>'''
(R/'apercu_pmd.html').write_text(html.replace('__DATA__',json.dumps(DATA,ensure_ascii=False,separators=(',',':'))))
print('Viewer bytes:',(R/'apercu_pmd.html').stat().st_size,'unique images',len(assets))
